  answerMode?: AskResultAnswerMode;
  generated?: GeneratedAnswer;
  statsAnswer?: StatsAnswer;
  passages: Passage[];
  graphContext?: GraphContext;
  /** Direct answers from the curated claims layer for biography-style questions, grouped per philosopher and topic. */
