/**
 * Why the item appears here: "adjudicated" (kept for the audit trail), "awaiting_third" (escalated to a third judge whose judgment is still outstanding) or "deadlock" (no majority possible, an arbiter is required). Majority-resolved items never appear in this list.
 */
export type EvalDisagreementResolution = typeof EvalDisagreementResolution[keyof typeof EvalDisagreementResolution];


export const EvalDisagreementResolution = {
  adjudicated: 'adjudicated',
  deadlock: 'deadlock',
  awaiting_third: 'awaiting_third',
} as const;

